pascalScript:
var
  cevap: Integer;

procedure RaporHazirla;
begin
  if CheckBox1.Checked then
  begin
    Header1.Visible := False;
    MasterData2.Visible := False;
  end;



  if DBCheckListBox1.SQLText <> '' then
  begin
    qm.SQL.Text := StringReplace(qm.SQL.Text,'--birimfiltresi',DBCheckListBox1.SQLText);
    qm1.SQL.Text := StringReplace(qm1.SQL.Text,'--birimfiltresi',DBCheckListBox1.SQLText);
  end;

  DialogPage1.ModalResult := mrOk;
end;

procedure RaporKapat;
begin
  cevap := MessageDlg('Raporu kapatmak istiyor musunuz?', 4, 3, 0);
  if cevap = mrYes then
  begin
    DialogPage1.ModalResult := mrCancel;
    Engine.StopReport;
  end
  else
  begin
    DialogPage1.ModalResult := mrNone;
  end;
end;

procedure Button1OnClick(Sender: TfrxComponent);
begin
  RaporHazirla;
end;

procedure CheckBox4OnClick(Sender: TfrxComponent);
begin
  if CheckBox4.Checked then
    DBCheckListBox1.CheckAll
  else
    DBCheckListBox1.UnCheckAll;
end;

procedure Button2OnClick(Sender: TfrxComponent);
begin
  RaporKapat;
end;

procedure DialogPage1OnKeyDown(Sender: TfrxComponent; var Key: Word; Shift: Integer);
begin
  if Key = 13 then
  begin
    RaporHazirla;
  end;

  if Key = 27 then
  begin
    RaporKapat;
  end;
end;

procedure CheckBox1OnClick(Sender: TfrxComponent);
begin
  if CheckBox1.Checked then
  begin
    CheckBox3.Checked := False;
    CheckBox3.Enabled := False;
  end
  else
  begin
    CheckBox3.Enabled := True;
  end;
end;

procedure CheckBox3OnClick(Sender: TfrxComponent);
begin
  if CheckBox3.Checked then
  begin
    CheckBox1.Checked := False;
    CheckBox1.Enabled := False;
  end
  else
  begin
    CheckBox1.Enabled := True;
  end;
end;


begin
  qbina.open;
  qbina.fetchall;
  qbirim.open;
  qbirim.fetchall;

  if <BinaIdList><>'' then
  begin
    qbina.SQL[1] := 'where id in (' + <BinaIdList> + ' )';
    qm.SQL.Text := StringReplace(qm.SQL.Text,'--BinaFiltresi','and b.bina_id in (' + <BinaIdList> + ' )');
    qm1.SQL.Text := StringReplace(qm1.SQL.Text,'--BinaFiltresi','and b.bina_id in (' + <BinaIdList> + ' )');
  end;
end.
